      command: "curl -sf http://localhost:9000/minio/health/live"
    install_hint: "Run: docker compose up -d minio"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let req = &config.requirements["minio"];
